#!/usr/bin/env python3
# SPDX-License-Identifier: CC0-1.0
"""Independent JSON/math fixtures for PiSP temporal denoise and HDR tone policy."""
import json
import math
from pathlib import Path
import sys

root = Path(__file__).resolve().parents[1]
lines = ['/* SPDX-License-Identifier: BSD-2-Clause */',
         '/* Raspberry Pi Ltd calibration; generated by generate_native_tuning_vectors.py. */',
         'struct temporal_vector { unsigned profile, hdr, frames; double gain;',
         '    unsigned constant, slope, threshold, sdn[5], cdn; };',
         'static const struct temporal_vector temporal_vectors[] = {']
names = ('ov5647', 'ov5647_noir', 'imx219', 'imx219_noir', 'imx477', 'imx477_noir',
         'imx708', 'imx708_noir', 'imx708_wide', 'imx708_wide_noir')

def field(x, bits, frac=0):
    return max(0, min((1 << bits)-1, math.floor(x*(1 << frac)+0.5)))

for profile, name in enumerate(names, 1):
    a = {k:v for item in json.loads((root/'data'/f'{name}-pisp.json').read_text())['algorithms'] for k,v in item.items()}
    for hdr, mode in enumerate(('normal', 'hdr')):
        d = a['rpi.denoise'][mode]; s, c, t = (d[k] for k in ('sdn', 'cdn', 'tdn'))
        for gain in (1, 4, 16, 64):
            nc, ns = (a['rpi.noise'][k]*math.sqrt(gain) for k in ('reference_constant', 'reference_slope'))
            for frames in (0, 1, 3, 7):
                b = s.get('backoff', 0.75)**frames
                dev = b*s['deviation_no_tdn']+(1-b)*s['deviation']
                dev2 = b*s['deviation_no_tdn']+(1-b)*s.get('deviation2', s['deviation'])
                strength = b*s['strength_no_tdn']+(1-b)*s['strength']
                cdn = c['deviation']*(b+(1-b)/3)
                values = [field(nc*t['deviation'],16), field(ns*t['deviation'],16,8), field(t['threshold'],16,16)]
                spatial = [field(nc*dev,16), field(ns*dev,16,8), field(nc*dev2,16), field(ns*dev2,16,8), field(1-strength,8,8)]
                lines.append('    {%d,%d,%d,%s,%s,{%s},%d},' %
                    (profile,hdr,frames,gain,','.join(map(str,values)),','.join(map(str,spatial)),field(cdn*ns+nc,16)))
lines += ['};', 'struct hdr_vector { unsigned bin, lut[64]; };', 'static const struct hdr_vector hdr_vectors[] = {']
for bin_number in (0, 8, 128, 512, 1023):
    # A histogram with all samples in one bin has this exact quantile mean.
    value = (bin_number+0.5)/1024
    gain = max(1, min(1.6, min(target/(value+0.01) for target in (0.65,0.28,0.25))))
    exponent = max(0.65, min(1, min(math.log(target+1e-6)/math.log(min(value*gain,1)+1e-6) for target in (0.03,0.15))))
    points = [(0,0)]
    for i in range(7):
        x = 512 << i
        y = min(x*gain/65536,1)**exponent*65536
        if i<2: y *= (0.5,0.75)[i]
        points.append((x,y))
    points.append((65536,65535))
    lut = []; previous = 0
    for j in range(1,65):
        x = j*512 if j<32 else (j-32)*1024+16384 if j<48 else (j-48)*2048+32768
        for (a,b),(c,d) in zip(points,points[1:]):
            if x<=c:
                nxt = int(b+(d-b)*(x-a)/(c-a)); break
        slope = min(16383,nxt-previous)
        lut.append(previous | (slope<<16)); previous += slope
    lines.append('    {%d,{%s}},' % (bin_number,','.join(map(str,lut))))
lines += ['};', 'struct spatial_vector { unsigned step_x, step_y, size_x, size_y, decimate; double gain[9]; };',
          'static const struct spatial_vector spatial_vectors[] = {']
# Independent region-space diffusion and interpolation, including clipped LSC
# grid steps and a decimated FE statistics grid.
grid = [[1+max(0,min(1,(0.06-(x+2*y)*65/65535)/0.05)) for x in range(32)] for y in range(32)]
for _ in range(3):
    grid = [[sum(grid[b][a] for a,b in ((x,y),(x-1,y),(x+1,y),(x,y-1),(x,y+1)) if 0<=a<32 and 0<=b<32)/
             sum(1 for a,b in ((x,y),(x-1,y),(x+1,y),(x,y-1),(x,y+1)) if 0<=a<32 and 0<=b<32)
             for x in range(32)] for y in range(32)]
for dx,dy,sx,sy,dec in ((8192,10922,32,24,0),(65535,65535,4,2,0),(8192,10922,16,12,1)):
    values=[]
    for y in (0,16,32):
        for x in (0,16,32):
            u=max(0,min(31,x*2**18/dx/(2**dec)/sx-0.5)); v=max(0,min(31,y*2**18/dy/(2**dec)/sy-0.5))
            a=int(u); b=int(v); c=min(31,a+1); d=min(31,b+1); u-=a; v-=b
            values.append((grid[b][a]*(1-u)+grid[b][c]*u)*(1-v)+(grid[d][a]*(1-u)+grid[d][c]*u)*v)
    lines.append('    {%d,%d,%d,%d,%d,{%s}},' % (dx,dy,sx,sy,dec,','.join(map(str,values))))
lines += ['};', '']
path = root/'tests/native_tuning_vectors.h'; output = '\n'.join(lines)
if '--check' in sys.argv:
    if path.read_text()!=output: raise SystemExit('Native tuning vectors are stale')
else:
    path.write_text(output)
